"""python -m uvicorn api.main:app --host 127.0.0.1 --port 8000"""
from contextlib import asynccontextmanager
from pathlib import Path
from fastapi import FastAPI
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from api.schemas import Customer, Prediction
from src.contract import ROOT
from src.model_loader import load_active
from src.predict import predict
from src.logging_utils import log_event


def create_app(config_path: Path = ROOT / "config" / "model.json", models_dir: Path = ROOT / "models"):
    @asynccontextmanager
    async def lifespan(app):
        # No artifact paths/versions are accepted from HTTP clients.
        try:
            app.state.model = load_active(config_path, models_dir)
        except Exception as error:
            log_event("model_load", "failed", error_type=type(error).__name__)
            raise
        log_event("model_load", "ready", app.state.model.metadata.model_version)
        yield
        app.state.model = None

    application = FastAPI(title="Customer Churn Prediction Service", version="1.0.0", lifespan=lifespan)

    @application.exception_handler(RequestValidationError)
    async def invalid_request(request, error):
        log_event("request_validation", "rejected", application.state.model.metadata.model_version, status_code=422)
        # Keep locations/messages useful without echoing customer values in errors.
        details = [{"loc": list(item["loc"]), "msg": item["msg"], "type": item["type"]}
                   for item in error.errors()]
        return JSONResponse(status_code=422, content={"detail": details})

    @application.get("/health")
    def health():
        return {"status": "ok", "model_loaded": True, "active_version": application.state.model.metadata.model_version}

    @application.get("/model-info")
    def model_info():
        metadata = application.state.model.metadata
        return {"active_version": metadata.model_version, "algorithm": metadata.algorithm,
                "trained_at": metadata.trained_at, "evaluation_metrics": metadata.metrics.model_dump(),
                "threshold": metadata.threshold, "feature_schema": Customer.model_json_schema()}

    @application.post("/predict", response_model=Prediction)
    def predict_customer(customer: Customer):
        loaded = application.state.model
        try:
            result = predict(customer, loaded)
        except Exception as error:
            log_event("inference", "failed", loaded.metadata.model_version, error_type=type(error).__name__, status_code=500)
            return JSONResponse(status_code=500, content={"detail": "Inference failed; consult operator logs."})
        log_event("inference", "ok", result.model_version, inference_latency_ms=result.inference_latency_ms, status_code=200)
        return result

    return application


app = create_app()

def predict(customer: Customer, loaded: LoadedModel) -> Prediction:
    start = perf_counter()

    frame = pd.DataFrame(
        [customer.model_dump()],
        columns=FEATURES,
    )
    probability = float(
        loaded.pipeline.predict_proba(frame)[0, 1]
    )
    label = "churn" if probability >= 0.5 else "stay"

    return Prediction(
        predicted_class=label,
        churn_probability=probability,
        model_version=loaded.metadata.model_version,
        inference_latency_ms=(perf_counter() - start) * 1000,
    )

"""Educational feature-shift checks, not a retraining or performance decision."""
import argparse
import json
from pathlib import Path
import numpy as np
import pandas as pd
from src.contract import NUMERIC, CATEGORIES, FEATURES, ROOT, validate_version


def reference_statistics(training: pd.DataFrame):
    return {
        "schema_version": 1, "training_rows": len(training),
        "numeric": {name: {"mean": float(training[name].mean()),
                           "std": float(training[name].std(ddof=0)),
                           "missing_fraction": float(training[name].isna().mean())} for name in NUMERIC},
        "categorical": {name: {str(k): float(v) for k, v in training[name].value_counts(normalize=True).items()}
                        for name in CATEGORIES},
    }


def check_drift(batch: pd.DataFrame, reference: dict):
    if len(batch) < 50:
        raise ValueError("Use at least 50 rows; tiny batches make distribution comparisons unstable.")
    if batch.columns.tolist() != FEATURES or reference.get("schema_version") != 1:
        raise ValueError("Batch/reference feature contract mismatch.")
    results = {}
    for name in NUMERIC:
        values = pd.to_numeric(batch[name], errors="raise")
        nonmissing = values.dropna().to_numpy(dtype=float)
        if len(nonmissing) == 0 or not np.isfinite(nonmissing).all():
            raise ValueError(f"{name} needs finite observed values.")
        baseline = reference["numeric"][name]
        change = abs(float(values.mean()) - baseline["mean"])
        # Constant-reference columns use an explicit equality test, not division by zero.
        scale = baseline["std"]
        shift = change / scale if scale > 0 else (0.0 if change == 0 else None)
        missing_change = abs(float(values.isna().mean()) - baseline["missing_fraction"])
        status = "DRIFT DETECTED" if shift is None or shift >= 0.5 or missing_change >= 0.1 else "OK"
        results[name] = {"status": status, "absolute_mean_shift_in_training_std": shift,
                         "missing_fraction_change": missing_change}
    for name, categories in CATEGORIES.items():
        if batch[name].isna().any() or not set(batch[name]).issubset(categories):
            raise ValueError(f"Unexpected or missing category in {name}.")
        observed = batch[name].value_counts(normalize=True).to_dict()
        expected = reference["categorical"][name]
        total_variation = 0.5 * sum(abs(observed.get(category, 0) - expected.get(category, 0)) for category in categories)
        results[name] = {"status": "WARNING" if total_variation >= 0.15 else "OK",
                         "total_variation_distance": total_variation}
    return {"rows": len(batch), "features": results,
            "action": "Investigate data quality and labeled performance; drift alone does not justify retraining."}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--version", default="v1")
    parser.add_argument("--batch", type=Path, required=True)
    args = parser.parse_args()
